package com.agilcalls.sdk

import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Static contract of the injected shim: the JS source is generated by
 * [AgilBridgeScript], so the nonce envelope, the top-frame guard and the origin
 * guard can be asserted without a WebView. Runtime behavior is covered by
 * `scripts/shim-smoke.mjs` (headless JS) and by [AgilBridgeEnvelopeTest].
 */
class AgilBridgeScriptTest {
    private val origin = "https://calls.example.com"

    @Test
    fun shimForwardsThroughTheNonceEnvelope() {
        val script = AgilBridgeScript.shim(origin, "nonce-123")
        assertTrue(script.contains(AgilBridgeEnvelope.NONCE_FIELD))
        assertTrue(script.contains(AgilBridgeEnvelope.MESSAGE_FIELD))
        assertTrue(script.contains("\"nonce-123\""))
        assertTrue(script.contains("JSON.stringify(data)"))
        // The envelope is the only forward call on the JS channel.
        assertTrue(script.contains("channel.postMessage(JSON.stringify("))
        // The raw widget object must never be forwarded un-enveloped.
        assertFalse(script.contains("channel.postMessage(JSON.stringify(data))"))
    }

    @Test
    fun shimOnlyInstallsInTheTopFrameOnTheWidgetOrigin() {
        val script = AgilBridgeScript.shim(origin, "nonce-123")
        assertTrue(script.contains("w.top !== w"))
        assertTrue(script.contains("w.location.origin !== \"$origin\""))
        assertTrue(script.contains("event.source !== w"))
        assertTrue(script.contains("if (typeof nonce !== 'string' || !nonce) return;"))
    }

    @Test
    fun shimRefusesToRunWithoutNonce() {
        val script = AgilBridgeScript.shim(origin, "")
        assertTrue(script.contains("if (typeof nonce !== 'string' || !nonce) return;"))
        assertTrue(script.contains("return;"))
    }

    @Test
    fun shimFiltersHostCommands() {
        val script = AgilBridgeScript.shim(origin, "nonce-123")
        assertFalse(script.contains("'agil:action'"))
        assertFalse(script.contains("'agil:chat-send'"))
        assertFalse(script.contains("'agil:theme'"))
        assertFalse(script.contains("'agil:config'"))
        assertFalse(script.contains("'agil:scheme'"))
    }

    @Test
    fun shimEscapesQuotesInOriginAndNonce() {
        val script = AgilBridgeScript.shim("https://evil.example/\");alert(1);//", "n\"once")
        // The quote is escaped, so the value cannot break out of the literal.
        assertTrue(script.contains("\\\");alert(1);//"))
        assertTrue(script.contains("n\\\"once"))
    }

    @Test
    fun postMessageScriptUsesThePageOriginAndEscapesScriptBreakers() {
        val json = org.json.JSONObject()
            .put("type", "agil:chat-send")
            .put("text", "a<b>&c\u2028d")
            .toString()
        val script = AgilBridgeScript.postMessage(json)
        assertTrue(script.contains("window.postMessage("))
        assertTrue(script.contains("window.location.origin"))
        assertFalse(script.contains("<b>"))
        assertTrue(script.contains("\\u003c"))
        assertTrue(script.contains("\\u0026"))
        assertTrue(script.contains("\\u2028"))
    }
}
